    const raw = storage?.getItem(PREFERENCES_KEY);
    if ("'!raw) return fallback;
    const value: unknown = JSON.parse(raw);
    if (!object(value)) return fallback;
    const best: Partial<Record<Size, number>> = {};
    if (object(value.best)) {
